package com.lyrashop.audit.dto;import java.time.Instant;import java.util.UUID;import com.lyrashop.audit.entity.AdminAuditLog;public record AdminAuditLogResponse(Long id,UUID adminId,String method,String action,String resourceType,String resourceId,String path,int responseStatus,String ipAddress,String userAgent,Instant createdAt){public static AdminAuditLogResponse from(AdminAuditLog l){return new AdminAuditLogResponse(l.getId(),l.getAdminId(),l.getMethod(),l.getAction(),l.getResourceType(),l.getResourceId(),l.getPath(),l.getResponseStatus(),l.getIpAddress(),l.getUserAgent(),l.getCreatedAt());}}
